SELECT DATE_TRUNC('WEEK', launch_date) AS week_start, CASE WHEN price >= 950 THEN 'LARGE' ELSE 'SMALL' END AS price_tier, COUNT(*) FILTER (WHERE category = 'Grocery') AS grocery_rows, STDDEV_SAMP(price) AS price_stddev, ROUND(SUM(price) / NULLIF(COUNT(CASE WHEN brand = 'Globex' THEN 1 END), 0), 2) AS price_per_globex, APPROX_PERCENTILE(stock_qty, ARRAY(0.25, 0.5, 0.75)) AS stock_qty_quartiles, ROUND(AVG(price), 2) AS avg_price, PERCENTILE_APPROX(stock_qty, 0.9) AS stock_qty_p90, RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', launch_date) ORDER BY STDDEV_SAMP(price) DESC) AS price_stddev_rank FROM products GROUP BY DATE_TRUNC('WEEK', launch_date), CASE WHEN price >= 950 THEN 'LARGE' ELSE 'SMALL' END ORDER BY avg_price ASC
